class Duration:
    def __init__(self, minutes):
        self.minutes = minutes

    @property
    def minutes(self):
        return self._minutes

    @minutes.setter
    def minutes(self, value):
        if value < 0:
            raise ValueError("minutes must be nonnegative")
        self._minutes = value

x = Duration(8)
x.minutes = 3
try:
    x.minutes = -2
except ValueError:
    print(x.minutes)
